-- Generated by scripts/reconcile_metrics.py from committed CSV files.
-- Run after seed.sql, only in the disposable acceptance database.
SET NOCOUNT ON;
CREATE TABLE #Contexts (Scenario NVARCHAR(100), DepartmentID INT, DoctorID INT,
    PatientID INT, MonthKey CHAR(7), Status VARCHAR(15));
INSERT #Contexts VALUES
-- CONTEXT_VALUES
;
CREATE TABLE #Expected (Scenario NVARCHAR(100), Metric NVARCHAR(100), Value DECIMAL(28,8));
INSERT #Expected VALUES
-- EXPECTED_VALUES
;
CREATE TABLE #Actual (Scenario NVARCHAR(100), Metric NVARCHAR(100), Value DECIMAL(28,8));
DECLARE @Scenario NVARCHAR(100), @DepartmentID INT, @DoctorID INT, @PatientID INT,
    @Month CHAR(7), @Status VARCHAR(15);
DECLARE cases CURSOR LOCAL FAST_FORWARD FOR SELECT * FROM #Contexts;
OPEN cases;
FETCH NEXT FROM cases INTO @Scenario,@DepartmentID,@DoctorID,@PatientID,@Month,@Status;
WHILE @@FETCH_STATUS=0
BEGIN
    SELECT * INTO #A FROM dbo.Appointment a WHERE
        (@DepartmentID IS NULL OR a.DepartmentID=@DepartmentID) AND
        (@DoctorID IS NULL OR a.DoctorID=@DoctorID) AND
        (@PatientID IS NULL OR a.PatientID=@PatientID) AND
        (@Month IS NULL OR CONVERT(CHAR(7),a.AppointmentDate,126)=@Month) AND
        (@Status IS NULL OR a.Status=@Status);
    -- Same selection without the doctor filter, for REMOVEFILTERS(Doctor) measures.
    SELECT * INTO #AD FROM dbo.Appointment a WHERE
        (@DepartmentID IS NULL OR a.DepartmentID=@DepartmentID) AND
        (@PatientID IS NULL OR a.PatientID=@PatientID) AND
        (@Month IS NULL OR CONVERT(CHAR(7),a.AppointmentDate,126)=@Month) AND
        (@Status IS NULL OR a.Status=@Status);
    SELECT r.* INTO #R FROM dbo.Medical_Record r JOIN #A a ON r.AppointmentID=a.AppointmentID;
    SELECT b.* INTO #B FROM dbo.Billing b JOIN #R r ON b.RecordID=r.RecordID;
    SELECT * INTO #Rooms FROM dbo.Room WHERE @DepartmentID IS NULL OR DepartmentID=@DepartmentID;
    SELECT s.* INTO #Stays FROM dbo.Room_Assignment s JOIN #Rooms r ON s.RoomID=r.RoomID
        WHERE s.DischargeDate IS NOT NULL AND (@PatientID IS NULL OR s.PatientID=@PatientID);
    -- Cast each branch before UNION: SQL decimal type unification can otherwise
    -- reduce rate/average scale when combined with high-precision SUM amounts.
    INSERT #Actual
    SELECT @Scenario,N'Appointments',CAST((NULLIF(COUNT(*),0)) AS DECIMAL(28,8)) FROM #A UNION ALL
    SELECT @Scenario,N'Completed appointments',CAST((NULLIF(COUNT(*),0)) AS DECIMAL(28,8)) FROM #A WHERE Status='Completed' UNION ALL
    SELECT @Scenario,N'Cancelled appointments',CAST((NULLIF(COUNT(*),0)) AS DECIMAL(28,8)) FROM #A WHERE Status='Cancelled' UNION ALL
    SELECT @Scenario,N'Scheduled appointments',CAST((NULLIF(COUNT(*),0)) AS DECIMAL(28,8)) FROM #A WHERE Status='Scheduled' UNION ALL
    SELECT @Scenario,N'Completion rate',CAST((CAST(SUM(CASE WHEN Status='Completed' THEN 1 ELSE 0 END) AS DECIMAL(28,8))/NULLIF(SUM(CASE WHEN Status IN ('Completed','Cancelled') THEN 1 ELSE 0 END),0)) AS DECIMAL(28,8)) FROM #A UNION ALL
    SELECT @Scenario,N'Cancellation rate',CAST((CAST(SUM(CASE WHEN Status='Cancelled' THEN 1 ELSE 0 END) AS DECIMAL(28,8))/NULLIF(SUM(CASE WHEN Status IN ('Completed','Cancelled') THEN 1 ELSE 0 END),0)) AS DECIMAL(28,8)) FROM #A UNION ALL
    SELECT @Scenario,N'Patients served',CAST((NULLIF(COUNT(DISTINCT PatientID),0)) AS DECIMAL(28,8)) FROM #A WHERE Status='Completed' UNION ALL
    SELECT @Scenario,N'Visits',CAST((NULLIF(COUNT(*),0)) AS DECIMAL(28,8)) FROM #R UNION ALL
    SELECT @Scenario,N'Prescriptions',CAST((NULLIF(COUNT(*),0)) AS DECIMAL(28,8)) FROM dbo.Prescription p JOIN #R r ON p.RecordID=r.RecordID UNION ALL
    SELECT @Scenario,N'Billed amount',CAST((SUM(TotalAmount)) AS DECIMAL(28,8)) FROM #B UNION ALL
    SELECT @Scenario,N'Collected amount',CAST((SUM(TotalAmount)) AS DECIMAL(28,8)) FROM #B WHERE PaymentStatus='Paid' UNION ALL
    SELECT @Scenario,N'Outstanding amount',CAST((SUM(TotalAmount)) AS DECIMAL(28,8)) FROM #B WHERE PaymentStatus='Unpaid' UNION ALL
    SELECT @Scenario,N'Collection rate',CAST((SUM(CASE WHEN PaymentStatus='Paid' THEN TotalAmount ELSE 0 END)/NULLIF(SUM(TotalAmount),0)) AS DECIMAL(28,8)) FROM #B UNION ALL
    SELECT @Scenario,N'Doctors with appointments',CAST((NULLIF(COUNT(DISTINCT DoctorID),0)) AS DECIMAL(28,8)) FROM #A UNION ALL
    SELECT @Scenario,N'Department doctors',CAST((NULLIF(COUNT(*),0)) AS DECIMAL(28,8)) FROM dbo.Doctor WHERE (@DepartmentID IS NULL OR DepartmentID=@DepartmentID) AND (@DoctorID IS NULL OR DoctorID=@DoctorID) UNION ALL
    SELECT @Scenario,N'Department staff',CAST((NULLIF(COUNT(*),0)) AS DECIMAL(28,8)) FROM dbo.Staff WHERE @DepartmentID IS NULL OR DepartmentID=@DepartmentID UNION ALL
    SELECT @Scenario,N'Rooms',CAST((NULLIF(COUNT(*),0)) AS DECIMAL(28,8)) FROM #Rooms UNION ALL
    SELECT @Scenario,N'Occupied rooms',CAST((NULLIF(COUNT(*),0)) AS DECIMAL(28,8)) FROM #Rooms WHERE AvailabilityStatus='Occupied' UNION ALL
    SELECT @Scenario,N'Snapshot occupancy',CAST((CAST(SUM(CASE WHEN AvailabilityStatus='Occupied' THEN 1 ELSE 0 END) AS DECIMAL(28,8))/NULLIF(COUNT(*),0)) AS DECIMAL(28,8)) FROM #Rooms UNION ALL
    SELECT @Scenario,N'Completed stays',CAST((NULLIF(COUNT(*),0)) AS DECIMAL(28,8)) FROM #Stays UNION ALL
    SELECT @Scenario,N'Average completed stay',CAST((AVG(CAST(DATEDIFF(DAY,AdmissionDate,DischargeDate) AS DECIMAL(28,8)))) AS DECIMAL(28,8)) FROM #Stays UNION ALL
    SELECT @Scenario,N'Repeat patients',CAST((NULLIF(COUNT(*),0)) AS DECIMAL(28,8)) FROM (SELECT PatientID FROM #A WHERE Status='Completed' GROUP BY PatientID HAVING COUNT(*)>1) p UNION ALL
    SELECT @Scenario,N'Completed YoY change',CAST((CAST(SUM(CASE WHEN YEAR(AppointmentDate)=2025 THEN 1 ELSE 0 END)-SUM(CASE WHEN YEAR(AppointmentDate)=2024 THEN 1 ELSE 0 END) AS DECIMAL(28,8))/NULLIF(SUM(CASE WHEN YEAR(AppointmentDate)=2024 THEN 1 ELSE 0 END),0)) AS DECIMAL(28,8)) FROM #A WHERE Status='Completed' UNION ALL
    SELECT @Scenario,N'Outstanding over 90 days',CAST((SUM(b.TotalAmount)) AS DECIMAL(28,8)) FROM #B b JOIN #R r ON b.RecordID=r.RecordID JOIN #A a ON r.AppointmentID=a.AppointmentID WHERE b.PaymentStatus='Unpaid' AND a.AppointmentDate<'2025-10-02' UNION ALL
    SELECT @Scenario,N'Outstanding over 90 days share',CAST((CAST(SUM(CASE WHEN b.PaymentStatus='Unpaid' AND a.AppointmentDate<'2025-10-02' THEN b.TotalAmount ELSE 0 END) AS DECIMAL(28,8))/NULLIF(SUM(CASE WHEN b.PaymentStatus='Unpaid' THEN b.TotalAmount ELSE 0 END),0)) AS DECIMAL(28,8)) FROM #B b JOIN #R r ON b.RecordID=r.RecordID JOIN #A a ON r.AppointmentID=a.AppointmentID UNION ALL
    SELECT @Scenario,N'Average bill per visit',CAST((CAST(SUM(TotalAmount) AS DECIMAL(28,8))/NULLIF((SELECT COUNT(*) FROM #R),0)) AS DECIMAL(28,8)) FROM #B UNION ALL
    SELECT @Scenario,N'Visits per patient',CAST((CAST(COUNT(*) AS DECIMAL(28,8))/NULLIF(COUNT(DISTINCT PatientID),0)) AS DECIMAL(28,8)) FROM #A WHERE Status='Completed' UNION ALL
    SELECT @Scenario,N'Highest doctor workload',CAST((MAX(n)) AS DECIMAL(28,8)) FROM (SELECT COUNT(*) n FROM #A WHERE Status='Completed' GROUP BY DoctorID) d UNION ALL
    SELECT @Scenario,N'Lowest doctor workload',CAST((MIN(n)) AS DECIMAL(28,8)) FROM (SELECT COUNT(*) n FROM #A WHERE Status='Completed' GROUP BY DoctorID) d UNION ALL
    SELECT @Scenario,N'Average completed per doctor',CAST((CAST(NULLIF(SUM(CASE WHEN Status='Completed' THEN 1 ELSE 0 END),0) AS DECIMAL(28,8))/NULLIF(COUNT(DISTINCT DoctorID),0)) AS DECIMAL(28,8)) FROM #AD UNION ALL
    SELECT @Scenario,N'Highest doctor cancellation rate',CAST((MAX(r)) AS DECIMAL(28,8)) FROM (SELECT CAST(SUM(CASE WHEN Status='Cancelled' THEN 1 ELSE 0 END) AS DECIMAL(28,8))/NULLIF(SUM(CASE WHEN Status IN ('Completed','Cancelled') THEN 1 ELSE 0 END),0) r FROM #A GROUP BY DoctorID) d UNION ALL
    SELECT @Scenario,N'Cancellation rate all doctors',CAST((CAST(SUM(CASE WHEN Status='Cancelled' THEN 1 ELSE 0 END) AS DECIMAL(28,8))/NULLIF(SUM(CASE WHEN Status IN ('Completed','Cancelled') THEN 1 ELSE 0 END),0)) AS DECIMAL(28,8)) FROM #AD;
    DROP TABLE #A,#AD,#R,#B,#Rooms,#Stays;
    FETCH NEXT FROM cases INTO @Scenario,@DepartmentID,@DoctorID,@PatientID,@Month,@Status;
END;
CLOSE cases;
DEALLOCATE cases;
IF EXISTS (SELECT 1 FROM #Expected e FULL JOIN #Actual a ON e.Scenario=a.Scenario AND e.Metric=a.Metric
    WHERE e.Scenario IS NULL OR a.Scenario IS NULL OR
        (e.Value IS NULL AND a.Value IS NOT NULL) OR (e.Value IS NOT NULL AND a.Value IS NULL) OR ABS(e.Value-a.Value)>0.000001)
BEGIN
    SELECT e.Scenario,e.Metric,e.Value Expected,a.Value Actual FROM #Expected e FULL JOIN #Actual a
        ON e.Scenario=a.Scenario AND e.Metric=a.Metric
        WHERE e.Scenario IS NULL OR a.Scenario IS NULL OR
        (e.Value IS NULL AND a.Value IS NOT NULL) OR (e.Value IS NOT NULL AND a.Value IS NULL) OR ABS(e.Value-a.Value)>0.000001;
    THROW 51200,'Metric reconciliation failed.',1;
END;
SELECT COUNT(*) AS PassedMetricChecks FROM #Actual;
PRINT 'PASS: SQL metrics match CSV oracle in all 17 filter contexts. DAX engine acceptance remains separate.';
DROP TABLE #Contexts,#Expected,#Actual;
